def ratelimit(method="POST", limit=10, interval=60, key_prefix="rl"):
    """
    Decorator that caps `method` requests per client (IP) per endpoint to `limit`
    within `interval` seconds, returning a 429 once the cap is reached.
    """

    def ratelimit_decorator(f):
        @functools.wraps(f)
        def ratelimit_function(*args, **kwargs):
            key = "{}:{}:{}".format(key_prefix, get_ip(), request.endpoint)

